/* @autogenerated */
import { Component, inject } from '@angular/core';
import { ResourceServer } from 'app/features/access/resource-server/model/resource-server.model';
import { ResourceServerRepository } from 'app/features/access/resource-server/repository/resource-server-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'resource-server-view-enable-action', standalone: false, template: '' })
export class ResourceServerViewEnableActionComponent extends ConfirmAction<ResourceServer> {
  readonly name = 'enable';
  protected readonly scope = 'access/resource-server';
  protected readonly repository = inject(ResourceServerRepository);

  protected override appliesTo(items: ResourceServer[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: ResourceServer[]) {
    return this.repository.enable(item.uid);
  }
}
